// TH14 v1.00b route B boss non-spell: st04bs2.ecl.txt::BossB3 (226-279)
// with wave helper BossB3_at (281-324). Source refs are per statement below.

const TIME_LIMIT: int = 3024;      // 120 opening buffer + 2900 window + 4 startup
const OPENING_BUFFER: int = 120;
const NATIVE_LIMIT: int = 2400;    // setInterrupt(0, 2500, 2400, "BossBCard3") slot-0 time

// TH14 word list (transcribe/th14/touhou-bullets.ecl); source type39=NOTE_BLUE,
// type42=REST. Colors are the source color slots.
const TH14_NOTE_BLUE: int = 992;
const TH14_REST: int = 1040;

// Source per-bullet EX chain (BossB3_at 294-309, append order, async=0 all serial):
//   rec0 ANIM(a=1)                         -> birth animation, omitted per policy
//   rec1 ANGLE_ACCEL(60, +0.05, +1deg)     -> omega=omega, speed += .05/frame
//   rec2 ANGLE_ACCEL(60, -0.05, -1deg)     -> omega=-omega, speed -= .05/frame
//   rec3 STEP(1,1,c4,90deg,0)              -> one tick, then angle 90deg and speed 0
//   rec4 SETSPRITE(type42,color3)          -> blue note becomes a rest
//   rec5 WAIT(60)
//   rec6 ANGLE_ACCEL(60, +inc, 0)          -> constant accel = linear ramp to 60*inc
// rec6 is a linear speed ramp along a fixed angle, so step_speed(60*inc,60) is the
// same trajectory without leaving POLAR enabled after the program ends.
// SETSPRITE keeps the birth radius in the target (radius 4 vs source re-read 5).
xformdef NOTE_CURVE(omega: angle, fall: fx) {
    set_ang_vel(omega);
    set_accel(0.05fx);
    wait(60);
    set_ang_vel(0deg - omega);
    set_accel(-0.05fx);
    wait(60);
    wait(1);
    stop_fx();
    set_angle(90deg);
    set_speed(0fx);
    set_sprite(TH14_REST, 3);
    wait(60);
    step_speed(fall, 60 + 65536 * EASE_LINEAR);
}

// BossB3_at 286-320: 18-way fixed-direction ring, random base angle per wave,
// speed 0.2, net birth distance 32 - 4*0.2 = 31.2 (etDist minus ANIM 4*speed).
sub fire_wave(omega: angle, fall: fx) {
    sh_reset(0);
    sh_sprite(0, TH14_NOTE_BLUE, 0);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 18, 1);
    sh_angle(0, rand(65536) as angle, 341 as angle);
    sh_speed(0, 0.2fx, 0fx);
    sh_dist(0, 31.2fx);
    sh_xform(0, NOTE_CURVE(omega, fall));
    sh_fire(0);
}

// BossB3_at 284: diffI(A,5,10,20,30); 311-319: per-wave wait 16/8/6/6.
sub fire_group(omega: angle, fall: fx) {
    var count: int = 5;
    var gap: int = 16;
    var rank: int = global(GVAR_RANK);
    if rank == 1 {
        count = 10;
        gap = 8;
    } else if rank == 2 {
        count = 20;
        gap = 6;
    } else if rank >= 3 {
        count = 30;
        gap = 6;
    }
    var i: int = 0;
    while i < count && self_int(1) < NATIVE_LIMIT {
        fire_wave(omega, fall);
        card_wait(gap);
        i = i + 1;
    }
}

// One logical movement step of source 412 moveRand(60,4,1.0). The mode argument does
// not override the velocity slot, which inherits linear (movement.md recipe).
// moveLimit(0,128,280,64) => position x[-140,140], y[96,160].
sub arm_step() {
    var k: int = self_int(0);
    if k < 60 {
        k = k + 1;
        set_self_int(0, k);
        var speed: fx = 0fx;
        if k < 60 { speed = ((60 - k) as fx) / 60fx; }
        var nx: fx = $self_x + self_fx(0) * speed;
        var ny: fx = $self_y + self_fx(1) * speed;
        if nx < -140fx { nx = -140fx; }
        if nx > 140fx { nx = 140fx; }
        if ny < 96fx { ny = 96fx; }
        if ny > 160fx { ny = 160fx; }
        move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
    }
}

// Source waits inside this attack advance the native clock and the movement arm.
sub card_wait(frames: int) {
    for i in 0..frames {
        if self_int(1) >= NATIVE_LIMIT { break; }
        wait(1);
        set_self_int(1, self_int(1) + 1);
        arm_step();
    }
}

// Source 412 direction selection for this limit: inner half-width 280/4=70,
// inner y 112..144, plus the source +/-pi/2 guard (0.05rad = 522 BAM).
sub move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = 0 - a; }
    } else if $self_y > 144fx {
        if a < 0 { a = 0 - a; }
        a = 0 - a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_step();
}

async sub source_enemy() {
    // BossB public entry: hurtbox/hitbox 48/48 (target radius = 48*0.5 = 24).
    // Shell keeps the source enemy undamageable; the source's 120-frame setInvuln
    // is subsumed by that target shell.
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    set_self_int(0, 60);   // moveRand step counter, 60 = idle
    set_self_int(1, 0);    // native clock since segment start
    // 253 movePosTime(60,4,0,128) from the previous segment's endpoint (0,144).
    // 247-249 zero-duration layer resets only clear in-flight motion.
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    card_wait(120);        // 259 wait(120)

    var omega: int = 182;  // 260 %F0 = 0.017453 rad = 1 deg/frame
    var fall: fx = 0.6fx;  // 300-309 rank inc 0.01/0.01/0.02/0.03 * 60 frames
    var rank: int = global(GVAR_RANK);
    if rank == 2 { fall = 1.2fx; }
    if rank >= 3 { fall = 1.8fx; }
    var outer: int = 120;  // 266-273 wait 120/120/100/80
    if rank == 2 { outer = 100; }
    if rank >= 3 { outer = 80; }

    loop {
        if self_int(1) >= NATIVE_LIMIT { break; }
        fire_group(omega as angle, fall);
        if self_int(1) >= NATIVE_LIMIT { break; }
        move_rand();       // 264 moveRand(60,4,1.0)
        omega = 0 - omega; // 265 %F0 *= -1
        card_wait(outer);
    }
    // Native timeout stops emission; the surviving bullets fly out in the tail.
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 144fx, 12500, 0, 0, 0, source_enemy);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
